/usr/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
Path('dev_tb.sv').write_text('''"'`timescale 1ns/1ps
module dev_tb;
    wire one;
    TopModule dut (.one(one));
    initial begin
        #0;
        if (one !== 1'"'b1) "'$fatal(1, "FAIL: one is not high at time-zero settling");
        repeat (100) begin
            #1;
            if (one !== 1'"'b1) "'$fatal(1, "FAIL: one is not high at time %0t", $time);
        end
        $display("PASS: one remained logic high at all 101 observations");
        $finish;
    end
    initial begin
        #200;
        $fatal(1, "FAIL: development simulation timeout");
    end
endmodule
'"''')
PY
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim.vvp candidate.sv dev_tb.sv > dev_compile.log 2>&1
compile_status="'$?
print -r -- "$compile_status" > dev_compile.exitcode
if [ "$compile_status" -eq 0 ]; then
 timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim.vvp > dev_simulation.log 2>&1
 print -r -- "$?" > dev_simulation.exitcode
fi
cat dev_compile.log dev_simulation.log'

